SELECT symbol, id, observed_at, created_at, price, delivery_status, outcome_reason FROM market_price_event WHERE (symbol='SHIBUSDT' AND observed_at BETWEEN '2026-10-12 07:15:04.000' AND '2026-10-12 07:15:44.000') OR (symbol='EGLDUSDT' AND observed_at BETWEEN '2026-10-11 20:55:00.000' AND '2026-10-11 20:55:03.100') OR (symbol='EGLDUSDT' AND observed_at BETWEEN '2026-10-11 22:40:01.000' AND '2026-10-11 22:40:03.200') OR (symbol='XRPUSDT' AND observed_at BETWEEN '2026-10-12 02:35:00.300' AND '2026-10-12 02:35:03.100') OR (symbol='DOGEUSDT' AND observed_at BETWEEN '2026-10-12 04:02:02.500' AND '2026-10-12 04:02:04.300') OR (symbol='SHIBUSDT' AND observed_at BETWEEN '2026-10-12 06:36:01.400' AND '2026-10-12 06:36:03.000') OR (symbol='ACEUSDT' AND observed_at BETWEEN '2026-10-12 09:57:02.400' AND '2026-10-12 09:57:04.300') ORDER BY symbol, observed_at LIMIT 300